import { existsSync, mkdirSync, readFileSync, writeFileSync } from "node:fs";
import { homedir } from "node:os";
import { join } from "node:path";
import { z } from "zod";

// ---------------------------------------------------------------------------
// Runtime configuration. Loaded from <dataDir>/config.json (generated by the
// installer) with environment-variable overrides. Secrets are NEVER stored in
// this file — tokens live in the auth store (0600) and pairing codes are
// generated on demand.
// ---------------------------------------------------------------------------

export const ConfigSchema = z.object({
  stationId: z.string(),
  stationName: z.string().default("Founda Dock Station"),
  // Default binding is loopback only. LAN mode must be enabled explicitly.
  host: z.string().default("127.0.0.1"),
  port: z.number().int().min(1).max(65535).default(4310),
  // Permitted workspace roots. The runtime refuses to serve anything outside these.
  workspaceRoots: z.array(z.string()).min(1),
  defaultShell: z.string().default("bash"),
  // Session token lifetime (hours).
  sessionTtlHours: z.number().int().min(1).max(24 * 30).default(24 * 7),
  // Pairing code lifetime (seconds) and rate limit (attempts per window).
  pairingTtlSeconds: z.number().int().min(30).max(3600).default(300),
  pairingMaxAttempts: z.number().int().min(1).max(50).default(5),
  pairingWindowSeconds: z.number().int().min(60).max(86400).default(600),
  // Metrics collection interval (ms). 0 disables the background loop.
  metricsIntervalMs: z.number().int().min(0).max(60000).default(5000),
  // Maximum concurrent WebSocket connections.
  maxWsConnections: z.number().int().min(1).max(100).default(20),
  // OpenCode / OpenClaw binary names (override when installed elsewhere).
  opencodeBin: z.string().default("opencode"),
  openclawBin: z.string().default("openclaw"),
});

export type RuntimeConfig = z.infer<typeof ConfigSchema>;

export function dataDir(): string {
  // FOUNDA_DOCK_HOME overrides the default ~/founda-dock (used by tests).
  return process.env.FOUNDA_DOCK_HOME ?? join(homedir(), "founda-dock");
}

export function configPath(): string {
  return join(dataDir(), "config", "config.json");
}

export function defaultConfig(): RuntimeConfig {
  const home = dataDir();
  return ConfigSchema.parse({
    stationId: `station-${Math.random().toString(36).slice(2, 10)}`,
    stationName: "Founda Dock Station",
    host: "127.0.0.1",
    port: 4310,
    workspaceRoots: [join(home, "projects")],
    defaultShell: "bash",
    sessionTtlHours: 24 * 7,
    pairingTtlSeconds: 300,
    pairingMaxAttempts: 5,
    pairingWindowSeconds: 600,
    metricsIntervalMs: 5000,
    maxWsConnections: 20,
    opencodeBin: "opencode",
    openclawBin: "openclaw",
  });
}

export function loadConfig(): RuntimeConfig {
  const path = configPath();
  if (!existsSync(path)) {
    const cfg = defaultConfig();
    saveConfig(cfg);
    return cfg;
  }
  const raw = JSON.parse(readFileSync(path, "utf8"));
  return ConfigSchema.parse(raw);
}

export function saveConfig(cfg: RuntimeConfig): void {
  const path = configPath();
  mkdirSync(join(dataDir(), "config"), { recursive: true });
  writeFileSync(path, JSON.stringify(cfg, null, 2), { mode: 0o600 });
}

export function ensureDirs(): void {
  const home = dataDir();
  for (const d of ["projects", "runtime", "config", "logs", "data", "backups"]) {
    mkdirSync(join(home, d), { recursive: true });
  }
}
